/*==============================================================================
  Axim CPQ — item classification
  ------------------------------------------------------------------------------
  Run after 05_service_objects.sql. REPLACES the prod_cat mechanism entirely:
  cpq.technology_category and cpq.category_discount_map are no longer read.

  WHY THE WHOLE HIERARCHY, AND WHY A PRODUCT LINE WHEN THERE IS A TECHNOLOGY

  Both were asked in a production-readiness review and both are fair.

  The hierarchy is loaded per item because it is the only source of the MODEL —
  Product Type: 6420, 5400 IP65, CSL60. That is what every specification rule
  matches on, and what a machine now has to carry to be classified as one. There
  is no smaller extract that answers "what model is this part": the question is
  asked of any item a rep can type.

  What is NOT loaded any more is product_group. It was loaded, stored, exposed as
  market_segment through two views, and read by nothing, which is the reviewer's
  point exactly. Product Class stays because the gap view reads it.

  Product Line is not Technology restated. 43 lines collapse to 7 technologies, and
  the collapse loses the thing the tool needs most:

      CIJ has 9 lines spanning 6 different ROLES — Corvus 6400 (printer),
      CIJ Print Heads (printhead), CIJ Consumables, CIJ Parts (spare),
      CIJ Accessories, CIJ Promotions.

  Technology says WHICH PRICE BOOK. Product Line says WHAT THE PART IS. Knowing an
  item is CIJ does not tell you whether it is a printer or a bottle of solvent, and
  that distinction is the whole basis of the machine list. Six more lines map to no
  technology at all — freight, installation labour, cross-technology spares — which
  a technology column cannot express either.

  Orbit does not carry "this is a printer". Three sources do, and they layer
  rather than compete, because none is a superset of the others:

    1. cpq.item_class_override   somebody classified it by hand. Always wins.
    2. cpq.item_hierarchy        Global_Product_Hierarchy, through the line map.
    3. (preview only)            the price-page sheet an item sat on.
    4. nothing                   appears in cpq.v_unclassified_item to be filled.

  Orbit stays the superset. Anything Orbit knows and none of these classify is
  visible in the gap view rather than silently absent — which is the failure this
  replaces, since the old empty mapping table meant the tool had no items at all.

  NOTHING HERE HAS BEEN RUN. Treat the first execution as a test on a restored
  copy.
==============================================================================*/

SET NOCOUNT ON;
GO
USE [AximQuote];
GO

/*------------------------------------------------------------------------------
  Product Line -> technology and type. The whole taxonomy, in 43 rows.
  Editable: it is a business decision, not logic.
------------------------------------------------------------------------------*/
IF OBJECT_ID('cpq.product_line_map') IS NULL
CREATE TABLE cpq.product_line_map (
    product_line   nvarchar(60)  NOT NULL PRIMARY KEY,
    product_class  nvarchar(60)  NULL,
    technology_cd  varchar(10)   NULL,        -- NULL = no price book yet
    item_role      varchar(20)   NOT NULL,
    is_quotable    bit           NOT NULL DEFAULT 1,
    confidence     varchar(12)   NOT NULL DEFAULT 'assumed',
    notes          nvarchar(400) NULL,
    updated_by     nvarchar(100) NULL,
    updated_at     datetime2(0)  NOT NULL DEFAULT SYSUTCDATETIME()
);
GO

/*  One row per part, straight from the hierarchy. product_type is the model
    (6420, 5400 IP65, PH4) and is what the rules match on.                   */
IF OBJECT_ID('cpq.item_hierarchy') IS NULL
CREATE TABLE cpq.item_hierarchy (
    item_no        varchar(25)  NOT NULL PRIMARY KEY,
    product_class  nvarchar(60) NULL,
    product_type   nvarchar(60) NULL,
    product_line   nvarchar(60) NULL,
    loaded_at      datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME()
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='ix_item_hier_line'
                 AND object_id=OBJECT_ID('cpq.item_hierarchy'))
    CREATE INDEX ix_item_hier_line ON cpq.item_hierarchy (product_line)
        INCLUDE (product_type, product_class);
GO

/*  The gap fill. A person classifies an item Orbit has and the hierarchy does
    not, and this always wins — it is the most recent human judgement.        */
IF OBJECT_ID('cpq.item_class_override') IS NULL
CREATE TABLE cpq.item_class_override (
    item_no       varchar(25)  NOT NULL PRIMARY KEY,
    technology_cd varchar(10)  NULL,
    item_role     varchar(20)  NOT NULL,
    model         nvarchar(60) NULL,
    is_quotable   bit          NOT NULL DEFAULT 1,
    reason        nvarchar(400) NULL,
    updated_by    nvarchar(100) NOT NULL,
    updated_at    datetime2(0)  NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT fk_override_tech FOREIGN KEY (technology_cd)
        REFERENCES cpq.technology(technology_cd)
);
GO

/*---- the 43 rows ----*/
DELETE FROM cpq.product_line_map WHERE updated_by IS NULL;
GO

