/*------------------------------------------------------------------------------
  Resolution. One view, one place the order is written down.

  THE MACHINE ROLE IS EARNED, NOT ASSUMED.

  product_line_map maps a whole Product Line to one role, and a line is a filing
  decision: "CSL LASER" holds the laser and everything bolted to it, "Hi Res" holds
  the printers and the hand cleaner somebody buys to wipe them down. So a line that
  maps to 'printer' hands that role to every part filed under it, and the tool
  offered "Handclean Hand Cleaner" as a machine.

  A machine carries a model. Where the line says 'printer' and neither an override
  nor Product Type names one, the resolved role is 'part' — quotable, priced, and
  absent from the machine list. cpq.v_classify_worklist is where a person promotes
  it back, and a manual override always wins here exactly as it does everywhere
  else: if somebody says this is a machine, it is one, model or no model.

  This can be wrong in the safe direction. A real machine whose model the hierarchy
  does not carry waits on the worklist. The alternative failed the other way, in
  front of a customer, at $46,400.
------------------------------------------------------------------------------*/
IF OBJECT_ID('cpq.v_item_class') IS NOT NULL DROP VIEW cpq.v_item_class;
GO
CREATE VIEW cpq.v_item_class
AS
SELECT
    i.item_no,
    COALESCE(o.technology_cd, m.technology_cd)          AS technology_cd,
    /*  NULLIF, because '' is not NULL and this test has to mean "carries no
        model". The loader wrote '' for every part whose Product Type names a kind
        of part rather than a machine, so this branch never once fired for a part
        that had a hierarchy row -- 2,340 parts on a printer line with no model
        stayed 'printer' here while every other part of the tool called them
        'part'. That is the rule that keeps hand cleaner out of the machine list,
        not running at all. The loader writes NULL now; this keeps the test honest
        for a row somebody enters by hand.  */
    CASE WHEN o.item_no IS NULL
          AND m.item_role = 'printer'
          AND NULLIF(h.product_type, N'') IS NULL
         THEN 'part'
         ELSE COALESCE(o.item_role, m.item_role)
    END                                                 AS item_role,
    COALESCE(o.model, NULLIF(h.product_type, N''))      AS model,
    h.product_line,

    CASE WHEN o.item_no IS NOT NULL THEN 'manual'
         WHEN m.product_line IS NOT NULL THEN 'hierarchy'
         ELSE 'unclassified' END                        AS class_source,
    /*  Quotable needs a technology, and 'ALL' is one.
        A promotion, a service offering or a training day belongs to every price book
        rather than to one. Before this they had to be filed under a single technology
        and go missing from the other six, or under none and become unquotable — so the
        revenue lines a rep adds to every quote were the ones the tool could not offer. */
    CASE WHEN COALESCE(o.is_quotable, m.is_quotable, 0) = 1
           AND COALESCE(o.technology_cd, m.technology_cd) IS NOT NULL
         THEN 1 ELSE 0 END                              AS is_quotable,
    COALESCE(o.updated_by, m.updated_by)                AS classified_by
FROM        mac.imitmidx_sql          AS i
LEFT JOIN   cpq.item_hierarchy        AS h ON h.item_no = i.item_no
LEFT JOIN   cpq.product_line_map      AS m ON m.product_line = h.product_line
LEFT JOIN   cpq.item_class_override   AS o ON o.item_no = i.item_no;
GO

/*  What a rep may quote, and what it costs. Replaces the prod_cat version.
    Price and cost still come from Orbit and are never stored here.          */
IF OBJECT_ID('cpq.v_quotable_item') IS NOT NULL DROP VIEW cpq.v_quotable_item;
GO
CREATE VIEW cpq.v_quotable_item
AS
SELECT
    i.item_no,
    i.item_desc_1                     AS description,
    c.technology_cd,
    c.item_role,
    c.model,
    c.product_line,
    c.class_source,
    i.prod_cat,                       -- carried for reference only; nothing reads it
    loc.list_price,
    loc.std_cost,
    i.unit_of_measure                 AS uom,
    CASE WHEN i.activity_cd = 'A' THEN 1 ELSE 0 END AS is_active
FROM        mac.imitmidx_sql   AS i
JOIN        cpq.v_item_class   AS c   ON c.item_no = i.item_no AND c.is_quotable = 1
LEFT JOIN   mac.iminvloc_sql   AS loc ON loc.item_no = i.item_no AND loc.loc = 'MAIN';
GO

/*------------------------------------------------------------------------------
  The gap query.

  Everything Orbit sells that nothing classifies. This is the worklist: filter
  it, classify a row, and it leaves the list. Ordered so the parts that have
  actually moved recently come first — an obsolete part nobody has ordered in
  four years is not worth anyone's afternoon.
------------------------------------------------------------------------------*/
IF OBJECT_ID('cpq.v_unclassified_item') IS NOT NULL DROP VIEW cpq.v_unclassified_item;
GO
CREATE VIEW cpq.v_unclassified_item
AS
SELECT
    i.item_no,
    i.item_desc_1                AS description,
    i.prod_cat,
    cf.description               AS prod_cat_desc,
    i.activity_cd,
    loc.list_price,
    loc.qty_on_hand,
    i.unit_of_measure            AS uom,
    h.product_line               AS hierarchy_line,   -- non-null = the LINE is unmapped
    h.product_class              AS hierarchy_class
FROM        mac.imitmidx_sql   AS i
LEFT JOIN   cpq.v_item_class   AS c   ON c.item_no = i.item_no
LEFT JOIN   cpq.item_hierarchy AS h   ON h.item_no = i.item_no
LEFT JOIN   mac.imcatfil_sql   AS cf  ON cf.prod_cat = i.prod_cat
LEFT JOIN   mac.iminvloc_sql   AS loc ON loc.item_no = i.item_no AND loc.loc = 'MAIN'
WHERE i.activity_cd = 'A'
  AND (c.is_quotable = 0 OR c.item_no IS NULL);
GO

/*------------------------------------------------------------------------------
  The worklist a person can actually finish.

  v_unclassified_item above is the raw gap and stays as it is — it answers "what
  does Orbit sell that we cannot quote". It is the wrong list to hand somebody,
  because most of it is inactive stock nobody will ever quote, and agreeing with a
  classification that is already correct does not remove a row from it. A number
  that does not go down when you do the work is not a worklist.

  This is the list where every row is a decision only a person can make:

    unearned machine   the line says printer, nothing names a model. Promote it
                       (an override with a model) or leave it as a part.
    unclassified       Orbit has it, no source classifies it, and it has moved
                       recently enough to be worth the afternoon.

  Both leave the list when the override is written, which is the property the raw
  gap view does not have. Filter columns are here rather than in the application so
  the count and the filtered list cannot disagree.
------------------------------------------------------------------------------*/
IF OBJECT_ID('cpq.v_classify_worklist') IS NOT NULL DROP VIEW cpq.v_classify_worklist;
GO
CREATE VIEW cpq.v_classify_worklist
AS
SELECT
    i.item_no,
    i.item_desc_1                AS description,
    'unearned machine'           AS reason,
    c.technology_cd,
    c.item_role,
    c.product_line,
    loc.list_price,
    loc.qty_on_hand
FROM        mac.imitmidx_sql   AS i
JOIN        cpq.v_item_class   AS c   ON c.item_no = i.item_no
LEFT JOIN   mac.iminvloc_sql   AS loc ON loc.item_no = i.item_no AND loc.loc = 'MAIN'
WHERE i.activity_cd = 'A'
  AND c.item_role = 'part'
  AND c.class_source <> 'manual'

UNION ALL

SELECT
    i.item_no,
    i.item_desc_1                AS description,
    'unclassified'               AS reason,
    NULL                         AS technology_cd,
    NULL                         AS item_role,
    h.product_line,
    loc.list_price,
    loc.qty_on_hand
FROM        mac.imitmidx_sql   AS i
LEFT JOIN   cpq.v_item_class   AS c   ON c.item_no = i.item_no
LEFT JOIN   cpq.item_hierarchy AS h   ON h.item_no = i.item_no
LEFT JOIN   mac.iminvloc_sql   AS loc ON loc.item_no = i.item_no AND loc.loc = 'MAIN'
WHERE i.activity_cd = 'A'
  AND (c.item_no IS NULL OR c.technology_cd IS NULL)
  /*  Recently enough to matter. An obsolete part nobody has ordered in four years
      is not worth anyone's afternoon, and putting it on the list is how a worklist
      becomes something people stop opening.                                    */
  AND EXISTS (SELECT 1 FROM mac.oelinhst_sql AS hl
               WHERE hl.item_no = i.item_no
                 AND hl.inv_dt >= DATEADD(month, -24, SYSUTCDATETIME()));
GO

PRINT '---------------------------------------------------------------';
PRINT ' Classification loaded.';
PRINT '';
PRINT ' cpq.v_quotable_item  now resolves through the hierarchy, not prod_cat.';
PRINT ' cpq.v_unclassified_item is the worklist for anything left over.';
PRINT '';
PRINT ' Check the rows in cpq.product_line_map where confidence = ''assumed''';
PRINT ' before trusting the machine list.';
PRINT '---------------------------------------------------------------';
GO
